import random

def get_min_dist_fast(seq, T):
    sums = 1
    for x in seq:
        sums |= (sums << x)

    mask = (1 << (T + 1)) - 1
    s_le_T = (sums & mask).bit_length() - 1

    rem = sums >> T
    if rem == 0:
        s_ge_T = float('inf')
    else:
        s_ge_T = T + (rem & -rem).bit_length() - 1

    return min(abs(s_le_T - T), abs(s_ge_T - T))

def hill_climbing(T, M, iterations=1000):
    # Start with a random sequence
    n = T // M + random.randint(0, 5)
    if n == 0: n = 1
    seq = [random.randint(1, M) for _ in range(n)]
    while sum(seq) < T:
        seq.append(random.randint(1, M))

    current_dist = get_min_dist_fast(seq, T)

    for _ in range(iterations):
        # Try to mutate the sequence
        new_seq = list(seq)
        mutation_type = random.random()

        if mutation_type < 0.4 and len(new_seq) > 1:
            # Change an element
            idx = random.randrange(len(new_seq))
            new_seq[idx] = max(1, min(M, new_seq[idx] + random.choice([-1, 1])))
        elif mutation_type < 0.7:
            # Add an element
            new_seq.append(random.randint(1, M))
        elif mutation_type < 0.9 and len(new_seq) > 1:
            # Remove an element
            idx = random.randrange(len(new_seq))
            new_seq.pop(idx)
        else:
            # Change two elements
            if len(new_seq) >= 2:
                idx1, idx2 = random.sample(range(len(new_seq)), 2)
                new_seq[idx1] = max(1, min(M, new_seq[idx1] + random.choice([-1, 1])))
                new_seq[idx2] = max(1, min(M, new_seq[idx2] + random.choice([-1, 1])))

        if sum(new_seq) < T:
            continue

        new_dist = get_min_dist_fast(new_seq, T)
        if new_dist >= current_dist:
            seq = new_seq
            current_dist = new_dist

    return current_dist, seq

